// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.string.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.STRF;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.junit.jupiter.api.Test;

class StringFunctionsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static Literal str(String s) {
		return VF.createLiteral(s);
	}

	private static Literal en(String s) {
		return VF.createLiteral(s, "en");
	}

	private static Literal integer(int i) {
		return VF.createLiteral(i);
	}

	@Test
	void trimFamilyPreservesLanguageTag() {
		assertThat(new Trim().evaluate(VF, en("  hi  "))).isEqualTo(en("hi"));
		assertThat(new LTrim().evaluate(VF, str("  hi  "))).isEqualTo(str("hi  "));
		assertThat(new RTrim().evaluate(VF, str("  hi  "))).isEqualTo(str("  hi"));
		assertThat(new Trim().evaluate(VF, str("xxhixy"), str("xy"))).isEqualTo(str("hi"));
		assertThat(new LTrim().evaluate(VF, str("xxhixy"), str("xy"))).isEqualTo(str("hixy"));
		assertThat(new RTrim().evaluate(VF, str("xxhixy"), str("xy"))).isEqualTo(str("xxhi"));
		Literal unchanged = str("hi");
		assertThat(new Trim().evaluate(VF, unchanged)).isSameAs(unchanged);
		assertThatThrownBy(() -> new Trim().evaluate(VF, integer(1))).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void padCountsCodePoints() {
		assertThat(new LPad().evaluate(VF, str("7"), integer(3), str("0"))).isEqualTo(str("007"));
		assertThat(new LPad().evaluate(VF, str("hi"), integer(5))).isEqualTo(str("   hi"));
		assertThat(new RPad().evaluate(VF, str("hi"), integer(5), str("ab"))).isEqualTo(str("hiaba"));
		assertThat(new LPad().evaluate(VF, str("😀"), integer(3), str("😀"))).isEqualTo(str("😀😀😀"));
		assertThat(new LPad().evaluate(VF, str("hello"), integer(2))).isEqualTo(str("he"));
		assertThat(new RPad().evaluate(VF, en("hello"), integer(2))).isEqualTo(en("he"));
		assertThat(new LPad().evaluate(VF, str("hello"), integer(0))).isEqualTo(str(""));
	}

	@Test
	void repeatReverseLeftRight() {
		assertThat(new Repeat().evaluate(VF, en("ab"), integer(3))).isEqualTo(en("ababab"));
		assertThat(new Repeat().evaluate(VF, str("ab"), integer(-1))).isEqualTo(str(""));
		assertThat(new Reverse().evaluate(VF, str("a😀b"))).isEqualTo(str("b😀a"));
		assertThat(new Left().evaluate(VF, str("a😀bcd"), integer(2))).isEqualTo(str("a😀"));
		assertThat(new Left().evaluate(VF, str("abcde"), integer(-2))).isEqualTo(str("abc"));
		assertThat(new Left().evaluate(VF, str("abc"), integer(10))).isEqualTo(str("abc"));
		assertThat(new Right().evaluate(VF, str("abc😀d"), integer(2))).isEqualTo(str("😀d"));
		assertThat(new Right().evaluate(VF, str("abcde"), integer(-2))).isEqualTo(str("cde"));
	}

	@Test
	void positionsAreOneBasedCodePoints() {
		assertThat(new Position().evaluate(VF, str("b"), str("😀ab")).intValue()).isEqualTo(3);
		assertThat(new Position().evaluate(VF, str("z"), str("abc")).intValue()).isEqualTo(0);
		assertThat(new Position().evaluate(VF, str("a"), en("banana")).intValue()).isEqualTo(2);
		assertThatThrownBy(() -> new Position().evaluate(VF, en("a"), str("banana")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new LastIndexOf().evaluate(VF, str("banana"), str("a")).intValue()).isEqualTo(6);
		assertThat(new LastIndexOf().evaluate(VF, str("😀a😀a"), str("a")).intValue()).isEqualTo(4);
		assertThat(new LastIndexOf().evaluate(VF, str("banana"), str("x")).intValue()).isEqualTo(0);
	}

	@Test
	void splitPartAndSplit() {
		assertThat(new SplitPart().evaluate(VF, str("a,b,c"), str(","), integer(2))).isEqualTo(str("b"));
		assertThat(new SplitPart().evaluate(VF, str("a,b,c"), str(","), integer(-1))).isEqualTo(str("c"));
		assertThat(new SplitPart().evaluate(VF, str("a,b,c"), str(","), integer(-3))).isEqualTo(str("a"));
		assertThat(new SplitPart().evaluate(VF, str("a,b,c"), str(","), integer(4))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("a,b,c"), str(","), integer(-4))).isEqualTo(str(""));
		assertThat(new SplitPart().evaluate(VF, str("a::b::c"), str("::"), integer(3))).isEqualTo(str("c"));
		assertThat(new SplitPart().evaluate(VF, str("abc"), str(""), integer(1))).isEqualTo(str("abc"));
		assertThatThrownBy(() -> new SplitPart().evaluate(VF, str("a"), str(","), integer(0)))
				.isInstanceOf(ValueExprEvaluationException.class);
		Literal array = new Split().evaluate(VF, str("a,b,,c"), str(","));
		assertThat(array.getCoreDatatype()).isEqualTo(CoreDatatype.RDF.JSON);
		assertThat(array.getLabel()).isEqualTo("[\"a\",\"b\",\"\",\"c\"]");
		assertThat(new Split().evaluate(VF, str("a😀"), str("")).getLabel()).isEqualTo("[\"a\",\"😀\"]");
	}

	@Test
	void concatWsFollowsConcatLanguageRules() {
		assertThat(new ConcatWs().evaluate(VF, str(", "), str("a"), str("b"), str("c"))).isEqualTo(str("a, b, c"));
		assertThat(new ConcatWs().evaluate(VF, en(" "), en("a"), en("b"))).isEqualTo(en("a b"));
		assertThat(new ConcatWs().evaluate(VF, str(" "), en("a"), en("b"))).isEqualTo(str("a b"));
		assertThat(new ConcatWs().evaluate(VF, str("-"))).isEqualTo(str(""));
		assertThatThrownBy(() -> new ConcatWs().evaluate(VF, str("-"), integer(1)))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void translateInitCapAsciiChr() {
		assertThat(new Translate().evaluate(VF, str("hello world"), str("lo "), str("01")))
				.isEqualTo(str("he001w1r0d"));
		assertThat(new Translate().evaluate(VF, en("abc"), str(""), str("x"))).isEqualTo(en("abc"));
		assertThat(new InitCap().evaluate(VF, str("hi THOMAS o'neil_x 3rd"))).isEqualTo(str("Hi Thomas O'Neil_X 3rd"));
		assertThat(new Ascii().evaluate(VF, str("😀x")).intValue()).isEqualTo(0x1F600);
		assertThat(new Ascii().evaluate(VF, str("")).intValue()).isEqualTo(0);
		assertThat(new Chr().evaluate(VF, integer(0x1F600))).isEqualTo(str("😀"));
		assertThat(new Chr().evaluate(VF, integer(65))).isEqualTo(str("A"));
		assertThatThrownBy(() -> new Chr().evaluate(VF, integer(0))).isInstanceOf(ValueExprEvaluationException.class);
	}

	@Test
	void normalizeForms() {
		String decomposed = "é";
		assertThat(new Normalize().evaluate(VF, str(decomposed))).isEqualTo(str("é"));
		assertThat(new Normalize().evaluate(VF, str("é"), str("nfd"))).isEqualTo(str(decomposed));
		assertThat(new Normalize().evaluate(VF, str("ﬁ"), str("NFKC"))).isEqualTo(str("fi"));
		assertThat(new Normalize().evaluate(VF, str(decomposed), str(""))).isEqualTo(str(decomposed));
		assertThatThrownBy(() -> new Normalize().evaluate(VF, str("x"), str("NFX")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new NormalizeUnicode().getURI())
				.isEqualTo("http://www.w3.org/2005/xpath-functions#normalize-unicode");
	}

	@Test
	void regexpExtract() {
		assertThat(new RegexpExtract().evaluate(VF, str("abc123def"), str("[0-9]+"))).isEqualTo(str("123"));
		assertThat(new RegexpExtract().evaluate(VF, en("abc123def"), str("([a-z]+)([0-9]+)"), integer(2)))
				.isEqualTo(en("123"));
		assertThat(new RegexpExtract().evaluate(VF, str("ABC"), str("b"), str("i"))).isEqualTo(str("B"));
		assertThat(new RegexpExtract().evaluate(VF, str("ABC"), str("x"))).isEqualTo(str(""));
		assertThatThrownBy(() -> new RegexpExtract().evaluate(VF, str("ABC"), str("(")))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThat(new RegexpExtractAll().evaluate(VF, str("a1b22c333"), str("[0-9]+")).getLabel())
				.isEqualTo("[\"1\",\"22\",\"333\"]");
		assertThat(new RegexpExtractAll().evaluate(VF, str("k=v;x=y"), str("(\\w)=(\\w)"), integer(1)).getLabel())
				.isEqualTo("[\"k\",\"x\"]");
	}

	@Test
	void allRegistered() {
		for (String name : new String[] { "trim", "ltrim", "rtrim", "lpad", "rpad", "repeat", "reverse", "left",
				"right", "position", "lastIndexOf", "splitPart", "split", "concatWs", "translate", "initCap", "ascii",
				"chr", "normalize", "regexpExtract", "regexpExtractAll" }) {
			assertThat(FunctionRegistry.getInstance().get(STRF.NAMESPACE + name)).as(name).isPresent();
		}
	}

	@Test
	void padRejectsHugeWidthsAsAnEvaluationError() {
		for (int width : new int[] { Integer.MAX_VALUE, 1_500_000_000, 1_000_000_000, (1 << 26) + 1 }) {
			Literal n = VF.createLiteral(BigInteger.valueOf(width));
			assertThatThrownBy(() -> new LPad().evaluate(VF, str("x"), n)).as("lpad " + width)
					.isInstanceOf(ValueExprEvaluationException.class);
			assertThatThrownBy(() -> new RPad().evaluate(VF, str("x"), n, str("ab"))).as("rpad " + width)
					.isInstanceOf(ValueExprEvaluationException.class);
		}
	}

	@Test
	void integerResultsUseXsdInteger() {
		assertThat(new Ascii().evaluate(VF, str("A")).getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(new Ascii().evaluate(VF, str("")).getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(new Position().evaluate(VF, str("b"), str("abc")).getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(new Position().evaluate(VF, str("z"), str("abc")).getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(new LastIndexOf().evaluate(VF, str("banana"), str("a")).getDatatype()).isEqualTo(XSD.INTEGER);
		assertThat(new LastIndexOf().evaluate(VF, str("banana"), str("x")).getDatatype()).isEqualTo(XSD.INTEGER);
	}
}
